"""Generate zoo/vendor/node_stub.step: a stand-in for a CM assembly proposal.

Box, bracket, and a sub-assembly of two glands (the same revolved solid placed
twice with different names and colours). Regenerated by a test so the file
never drifts from this generator.
"""
from pathlib import Path

from build123d import (
    Axis,
    Box,
    Color,
    Compound,
    Location,
    Plane,
    Polyline,
    export_step,
    make_face,
    revolve,
)

OUT = Path(__file__).with_name("node_stub.step")


def build() -> Compound:
    box = Box(60, 40, 30)
    box.label, box.color = "box", Color(0.75, 0.75, 0.78)
    bracket = Box(60, 3, 50).moved(Location((0, -21.5, 10)))
    bracket.label, bracket.color = "bracket", Color(0.27, 0.51, 0.71)
    profile = Plane.XZ * make_face(Polyline((0, 0), (8, 0), (8, 5), (6, 5), (6, 20), (0, 20), close=True))
    gland = revolve(profile, Axis.Z, 360)
    g1 = gland.moved(Location((-15, 20, 0), (90, 0, 0)))
    g2 = gland.moved(Location((15, 20, 0), (90, 0, 0)))
    g1.label, g1.color = "gland_1", Color(1.0, 0.65, 0.0)
    g2.label, g2.color = "gland_2", Color(0.9, 0.2, 0.1)
    glands = Compound(children=[g1, g2])
    glands.label = "glands"
    node = Compound(children=[box, bracket, glands])
    node.label = "node"
    return node


if __name__ == "__main__":
    export_step(build(), OUT, timestamp="2026-09-03T00:00:00")
    print(f"wrote {OUT} ({OUT.stat().st_size} bytes)")
